90	struct cfl_variant *cfl_variant_create_from_string_s(char *value, size_t value_size)
91	{
92	    struct cfl_variant *instance;
93	
94	    instance = cfl_variant_create();
95	
96	    if (instance != NULL) {
97	        instance->data.as_string = cfl_sds_create_len(value, value_size);
98	        if (instance->data.as_string == NULL) {
99	            free(instance);
100	            instance = NULL;
101	        }
102	        else {
103	            instance->type = CFL_VARIANT_STRING;
104	        }
105	    }
106	
107	    return instance;
108	}
109	
110	struct cfl_variant *cfl_variant_create_from_string(char *value)
111	{
112	    return cfl_variant_create_from_string_s(value, strlen(value));
