117	int cfl_array_append(struct cfl_array *array,
118	                     struct cfl_variant *value)
119	{
120	    void *tmp;
121	    size_t new_slot_count;
122	    size_t new_size;
123	
124	    if (array->entry_count >= array->slot_count) {
125	        /*
126	         * if there is no more space but the caller allowed to resize
127	         * the array, just double the size. Yeah, this is scary and should
128	         * be used only when the caller 'knows this is safe to do' because
129	         * it controls the input data.
130	         */
131	        if (array->resizable) {
132	            /* set new number of slots and total size */
133	            new_slot_count = (array->slot_count * 2);
134	            new_size = (new_slot_count * sizeof(void *));
135	
136	            tmp = realloc(array->entries, new_size);
137	            if (!tmp) {
138	                cfl_report_runtime_error();
139	                return -1;
140	            }
141	            array->slot_count = new_slot_count;
142	            array->entries = tmp;
143	        }
144	        else {
145	            return -1;
146	        }
147	    }
148	    array->entries[array->entry_count++] = value;
149	
150	    return 0;
151	}
